<script setup lang="ts">
import {phase} from '../animation/timeline';
defineProps<{index:number,count:number,progress:number,playing:boolean,speed:number,label?:string}>();
const emit=defineEmits<{seek:[number],toggle:[],speed:[number]}>();
</script>
<template><div class="motion-controls" data-testid="motion-controls"><div class="motion-status"><span class="motion-dot" :class="{playing}"/><strong>{{label}}</strong><span>{{phase(progress)}}</span><span class="motion-event-count">{{count?index+1:0}} / {{count}} 事件</span></div><div class="replay"><button title="重置" @click="emit('seek',0)">↺</button><button :disabled="index===0&&progress===0" @click="emit('seek',Math.max(0,index-1))">上一步</button><button class="primary" data-testid="motion-play" :disabled="!count" @click="emit('toggle')">{{playing?'Ⅱ 暂停':'▶ 播放'}}</button><button :disabled="index>=count-1" @click="emit('seek',index+1)">下一步</button><input type="range" aria-label="动画进度" :min="0" :max="Math.max(0,count-1)" :value="index" @input="emit('seek',Number(($event.target as HTMLInputElement).value))"><select :value="speed" aria-label="动画速度" @change="emit('speed',Number(($event.target as HTMLSelectElement).value))"><option :value=".5">0.5×</option><option :value="1">1×</option><option :value="2">2×</option><option :value="4">4×</option></select></div><div class="motion-phase-bar"><i :style="{transform:`scaleX(${progress})`}"/></div></div></template>
